#include "mongoose.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
/* Lexical semantic scopes. Function names are predeclared per block to allow recursion/forward calls. */
typedef struct Scope{struct Scope*parent;Name*names;int*kinds;size_t n,c;}Scope;
static bool same(Name a,Name b){return a.length==b.length&&!memcmp(a.name,b.name,a.length);}
static int lookup(Scope*s,Name n){for(;s;s=s->parent)for(size_t i=0;i<s->n;i++)if(same(s->names[i],n))return s->kinds[i];return 0;}
static bool define(Scope*s,Name n,int k,Token t,Diagnostic*e){for(size_t i=0;i<s->n;i++)if(same(s->names[i],n)){snprintf(e->message,sizeof e->message,"duplicate declaration '%.*s'",(int)n.length,n.name);e->line=t.line;e->column=t.column;return false;}if(s->n==s->c){size_t c=s->c?s->c*2:8;Name*a=realloc(s->names,c*sizeof*a);if(!a)return false;s->names=a;int*b=realloc(s->kinds,c*sizeof*b);if(!b)return false;s->kinds=b;s->c=c;}s->names[s->n]=n;s->kinds[s->n++]=k;return true;}
static bool sem(Node*n,Scope*s,bool fn,Diagnostic*e);
static bool semblock(Node*n,Scope*parent,bool fn,Diagnostic*e){Scope s={.parent=parent};for(size_t i=0;i<n->as.list.count;i++){Node*x=n->as.list.items[i];if(x->kind==N_FUNCTION&&!define(&s,x->as.function.name,2,x->token,e))goto bad;}for(size_t i=0;i<n->as.list.count;i++)if(!sem(n->as.list.items[i],&s,fn,e))goto bad;free(s.names);free(s.kinds);return true;bad:free(s.names);free(s.kinds);return false;}
static bool sem(Node*n,Scope*s,bool fn,Diagnostic*e){if(!n)return true;switch(n->kind){case N_PROGRAM:case N_BLOCK:return semblock(n,s,fn,e);case N_VAR:if(!sem(n->as.var.value,s,fn,e))return false;return define(s,n->as.var.name,1,n->token,e);case N_IDENT:if(!lookup(s,n->as.name)){snprintf(e->message,sizeof e->message,"undefined identifier '%.*s'",(int)n->as.name.length,n->as.name.name);e->line=n->token.line;e->column=n->token.column;return false;}return true;case N_FUNCTION:{Scope local={.parent=s};for(size_t i=0;i<n->as.function.param_count;i++)if(!define(&local,n->as.function.params[i],1,n->token,e)){free(local.names);free(local.kinds);return false;}bool ok=semblock(n->as.function.body,&local,true,e);free(local.names);free(local.kinds);return ok;}case N_IF:return sem(n->as.conditional.condition,s,fn,e)&&sem(n->as.conditional.then_branch,s,fn,e)&&sem(n->as.conditional.else_branch,s,fn,e);case N_RETURN:if(!fn){snprintf(e->message,sizeof e->message,"return outside function");e->line=n->token.line;e->column=n->token.column;return false;}return sem(n->as.ret.value,s,fn,e);case N_CALL:if(!((n->as.call.name.length==9&&!memcmp(n->as.call.name.name,"new_array",9))||(n->as.call.name.length==5&&!memcmp(n->as.call.name.name,"print",5)))&&lookup(s,n->as.call.name)!=2){snprintf(e->message,sizeof e->message,"unknown function '%.*s'",(int)n->as.call.name.length,n->as.call.name.name);e->line=n->token.line;e->column=n->token.column;return false;}for(size_t i=0;i<n->as.call.arg_count;i++)if(!sem(n->as.call.args[i],s,fn,e))return false;return true;case N_UNARY:return sem(n->as.unary.operand,s,fn,e);case N_BINARY:return sem(n->as.binary.left,s,fn,e)&&sem(n->as.binary.right,s,fn,e);case N_INDEX:return sem(n->as.index.target,s,fn,e)&&sem(n->as.index.index,s,fn,e);case N_ASSIGN:if(n->as.assign.target->kind!=N_IDENT&&n->as.assign.target->kind!=N_INDEX){snprintf(e->message,sizeof e->message,"invalid assignment target");e->line=n->token.line;e->column=n->token.column;return false;}if(n->as.assign.target->kind==N_IDENT&&lookup(s,n->as.assign.target->as.name)!=1){snprintf(e->message,sizeof e->message,"assignment to undefined variable");e->line=n->token.line;e->column=n->token.column;return false;}return sem(n->as.assign.target,s,fn,e)&&sem(n->as.assign.value,s,fn,e);default:return true;}}
bool analyze_ast(const Ast*a,Diagnostic*e){if(!a||!a->root||!e)return false;memset(e,0,sizeof*e);Scope g={0};bool ok=sem(a->root,&g,false,e);free(g.names);free(g.kinds);return ok;}

